7	  static func monotonicSeconds() -> Double {
8	    var ts = timespec()
9	    clock_gettime(CLOCK_MONOTONIC, &ts)
10	    return Double(ts.tv_sec) + Double(ts.tv_nsec) / 1_000_000_000
11	  }
12	}
