27	/// A byte buffer that drains to a descriptor via a write-then-compact loop — the shared mechanics
28	/// behind `SessionConnection`'s outbound reply queue and `PTYSession`'s outbound pty input queue.
29	/// Those were the same shape (append-only buffer, read cursor, threshold-based compaction at
30	/// 1<<16 bytes) implemented twice, and had already drifted apart on outcome handling. This owns
31	/// only the mechanics; callers keep their own outcome handling explicit — admission limits on
32	/// enqueue, whether to clear the buffer on a hard write failure — as caller-side concerns, not a
33	/// flag on this type.
34	struct SessionByteQueue {
35	  private var buffer: [UInt8] = []
36	  private var offset = 0
37	
38	  var pendingByteCount: Int { buffer.count - offset }
39	  var hasPendingOutput: Bool { pendingByteCount > 0 }
40	
41	  mutating func enqueue(_ bytes: [UInt8]) {
42	    buffer.append(contentsOf: bytes)
43	  }
44	
45	  /// Write until the buffer drains, a write would block, or one fails. On drain or wouldBlock the
46	  /// buffer is left correctly positioned for the next call (fully reset, or compacted once the
47	  /// consumed prefix crosses the 1<<16 threshold) — `.failed` leaves it untouched; only the caller
48	  /// knows whether a hard failure means "discard everything" (PTYSession does) or "the whole
49	  /// connection is about to be torn down anyway" (SessionConnection does).
50	  @discardableResult
51	  mutating func drain(to descriptor: Int32) -> SessionWriteOutcome {
52	    while offset < buffer.count {
53	      switch SessionIO.write(descriptor, buffer, from: offset) {
54	      case .wrote(let count):
55	        offset += count
56	      case .wouldBlock:
57	        compact()
58	        return .wouldBlock
59	      case .failed:
60	        return .failed
61	      }
62	    }
63	    buffer.removeAll(keepingCapacity: true)
64	    offset = 0
65	    return .wrote(0)
66	  }
67	
68	  /// Discard everything — for a caller that treats a hard write failure as "start clean" rather
69	  /// than "the buffer's fate no longer matters" (see `drain`'s doc).
70	  mutating func clear() {
71	    buffer.removeAll(keepingCapacity: true)
72	    offset = 0
73	  }
74	
75	  /// Only reachable with `offset < buffer.count` (the `wouldBlock` case above, still inside the
76	  /// loop) — so `offset == buffer.count` can never happen here; the drained-to-completion path
77	  /// resets directly in `drain` instead. Compacts once the consumed prefix is large enough to be
78	  /// worth the `removeFirst` copy, rather than on every partial write.
79	  private mutating func compact() {
80	    guard offset >= 1 << 16 else { return }
81	    buffer.removeFirst(offset)
82	    offset = 0
83	  }
84	}
