87	  static let chunkSize = 64 * 1024
88	
89	  static func setNonBlocking(_ descriptor: Int32) {
90	    let flags = fcntl(descriptor, F_GETFL, 0)
91	    guard flags >= 0 else { return }
92	    _ = fcntl(descriptor, F_SETFL, flags | O_NONBLOCK)
93	  }
94	
95	  static func setCloseOnExec(_ descriptor: Int32) {
96	    let flags = fcntl(descriptor, F_GETFD, 0)
97	    guard flags >= 0 else { return }
98	    _ = fcntl(descriptor, F_SETFD, flags | FD_CLOEXEC)
99	  }
100	
101	  static func read(_ descriptor: Int32, limit: Int = chunkSize) -> SessionReadOutcome {
102	    var count = 0
103	    let buffer = [UInt8](unsafeUninitializedCapacity: limit) { pointer, initialized in
104	      count = Darwin.read(descriptor, pointer.baseAddress, limit)
105	      initialized = max(count, 0)
106	    }
107	    if count > 0 { return .bytes(buffer) }
108	    if count == 0 { return .endOfFile }
109	    switch errno {
110	    case EINTR, EAGAIN:
111	      return .wouldBlock
112	    default:
113	      return .failed
114	    }
115	  }
116	
117	  static func write(_ descriptor: Int32, _ bytes: [UInt8], from offset: Int) -> SessionWriteOutcome
118	  {
119	    guard offset < bytes.count else { return .wrote(0) }
120	    let count = bytes.withUnsafeBytes { pointer -> Int in
121	      guard let base = pointer.baseAddress else { return -1 }
122	      return Darwin.write(descriptor, base.advanced(by: offset), bytes.count - offset)
123	    }
124	    if count >= 0 { return .wrote(count) }
125	    switch errno {
126	    case EINTR, EAGAIN:
127	      return .wouldBlock
128	    default:
129	      return .failed
130	    }
131	  }
