133	  @discardableResult
134	  static func writeAll(_ descriptor: Int32, _ bytes: [UInt8]) -> Bool {
135	    var offset = 0
136	    while offset < bytes.count {
137	      switch write(descriptor, bytes, from: offset) {
138	      case .wrote(let count):
139	        offset += count
140	      case .wouldBlock:
141	        var pollfd = pollfd(fd: descriptor, events: Int16(POLLOUT), revents: 0)
142	        let ready = poll(&pollfd, 1, 1000)
143	        if ready < 0, errno != EINTR { return false }
144	        continue
145	      case .failed:
146	        return false
147	      }
148	    }
149	    return true
150	  }
